class Account
  attr_reader :lock, :balance
  def initialize
    @lock = Mutex.new                 # published lock
    @balance = 0
  end

  def transfer_to(other, amount)
    lock.synchronize do
      other.lock.synchronize {        # fixed order: self, then other
        @balance -= amount
        other.send(:apply, amount)    # caller already holds the lock
      }
    end
  end

  private def apply(delta) = @balance += delta
end
